import XCTest

/// Base class for Flow Review's generated test cases.
///
/// Subclasses (generated by `flow-review run`/`init`) call `runFlow(id:)`
/// once per test method. Everything about *what* the flow does comes from a
/// JSON file baked into the UI test bundle's resources at build time -- the
/// Swift side never parses YAML or reaches out over the network.
class FlowReviewTestCase: XCTestCase {
    override func setUpWithError() throws {
        continueAfterFailure = false
    }

    func runFlow(id: String, file: StaticString = #file, line: UInt = #line) throws {
        let bundle = Bundle(for: FlowReviewTestCase.self)
        guard let flowURL = bundle.url(forResource: id, withExtension: "json") else {
            XCTFail("Flow Review: could not find bundled flow definition '\(id).json'. Run `flow-review run` (not raw xcodebuild) so definitions get generated.", file: file, line: line)
            return
        }
        let flow = try JSONDecoder().decode(FlowDefinition.self, from: Data(contentsOf: flowURL))

        var reviewDelayMs = 0
        if let ctxURL = bundle.url(forResource: "run_context", withExtension: "json"),
           let ctx = try? JSONDecoder().decode(RunContext.self, from: Data(contentsOf: ctxURL)) {
            reviewDelayMs = ctx.reviewDelayMs
        }
        // A flow can request a different cadence than the run-wide default.
        if let flowDelay = flow.reviewDelayMs {
            reviewDelayMs = flowDelay
        }

        let resultsRoot = FileManager.default.temporaryDirectory
            .appendingPathComponent("FlowReviewResults", isDirectory: true)
            .appendingPathComponent(id, isDirectory: true)
        try? FileManager.default.removeItem(at: resultsRoot)
        try FileManager.default.createDirectory(at: resultsRoot, withIntermediateDirectories: true)

        let app = XCUIApplication()
        let engine = FlowEngine(app: app, flow: flow, reviewDelayMs: reviewDelayMs, resultsDir: resultsRoot)
        try engine.run()
    }
}
